set -a; [ -f ./.env ] && . ./.env; [ -f "${OMNIRUN_OUTPUT%/outputs}/.env" ] && . "${OMNIRUN_OUTPUT%/outputs}/.env"; set +a; export PYTHONPATH=src
PY=python; [ -n "${VIRTUAL_ENV:-}" ] && PY="$VIRTUAL_ENV/bin/python"
F=results/noise_v3/fits_r3b; C=results/noise_v2/rounds/round1/supports; mkdir -p "$F/logs" "$C"
exec > >(tee -a "$F/michaels_fly125_standby_job.log") 2>&1
T0=$(date +%s)
echo  | base64 -d > /tmp/upload.py
echo  | base64 -d > /tmp/summ.py
export AWS_DEFAULT_REGION=auto AWS_ENDPOINT_URL="https://$R2_ACCOUNT_ID.r2.cloudflarestorage.com"
JOB="${OMNIRUN_JOB:-$(basename "${OMNIRUN_OUTPUT%/outputs}")}"
DEST="s3://omnirun-artifacts/$JOB/outputs/results/noise_v3/fits_r3b"
if command -v aws >/dev/null 2>&1; then AWS=aws
elif command -v uvx >/dev/null 2>&1; then AWS="uvx --quiet --from awscli aws"
else python3 -m pip install -q --user awscli >/dev/null 2>&1; AWS="python3 -m awscli"; fi
sync_out() { $AWS s3 sync --only-show-errors --endpoint-url "$AWS_ENDPOINT_URL" "$F" "$DEST" \
  || $PY /tmp/upload.py "$JOB/outputs" "$F"; }
dump_err() { for f in "$1"/raw/*.err "$1"/raw/*.log; do [ -f "$f" ] && { echo "=== $f"; cat "$f"; }; done; }
stamp() { while IFS= read -r l; do printf '%s %s\n' "$(date -u +%H:%M:%S)" "$l"; done; }
echo "V3R3 job=$JOB dest=$DEST sha=$(git rev-parse --short=12 HEAD 2>/dev/null) host=$(hostname) nproc=$(nproc)"
nvidia-smi --query-gpu=name,memory.total,driver_version --format=csv
( while sleep 600; do sync_out; done ) >/dev/null 2>&1 & SYNC_PID=$!
$PY -c "import torch; print('V3R3 torch', torch.__version__, 'cuda', torch.cuda.is_available(), torch.cuda.get_device_name(0) if torch.cuda.is_available() else '-')"
S=/tmp/supports_michaels_fly125_standby; mkdir -p "$S"
echo "V3R3 spec: set=michaels-standby name=michaels_fly125_standby wander=results/noise_v3/wander/michaels_ujk.json extra='' init=results/noise_v2/rounds/round3/fits/michaels_fly125_standby__flight.json sched='--ridge-step --lbfgs-rtol 0 --rounds 20 --lbfgs-frames 64 --lbfgs-iters 150' seeds='0 1 2 3' parallel=1"
$PY scripts/noise_v2_supports.py build --set michaels-standby --out "$S" > "$F/michaels_fly125_standby_build.log" 2>&1; EB=$?
tail -2 "$F/michaels_fly125_standby_build.log"
for f in "$S"/*.npz; do b=$(basename "$f"); [ -f "$C/$b" ] || { cp "$f" "$C/.tmp.$$.$b" && mv -f "$C/.tmp.$$.$b" "$C/$b"; }; done
echo "V3R3 build exit=$EB wall_s=$(( $(date +%s) - T0 ))"
run_seed() {
  N=$1; T1=$(date +%s)
  echo "V3R3 seed=$N start"
  $PY -u scripts/noise_v2_fit.py flight --mode flight_v3 --set michaels-standby --name michaels_fly125_standby \
    --wander results/noise_v3/wander/michaels_ujk.json \
    --channel-gains results/noise_v2/mic_gains/mic_gains.json --channel-gains-rig michaels  \
    --init-from results/noise_v2/rounds/round3/fits/michaels_fly125_standby__flight.json --ridge-step --lbfgs-rtol 0 --rounds 20 --lbfgs-frames 64 --lbfgs-iters 150 --max-frames 0 --seed $N --restart-tag s$N --jobs 1 --threads 4 --device cuda \
    --progress 50 --out "$F" --grid-dir "$F/grid/michaels_fly125_standby_s$N" 2>&1 | grep -v Warn | stamp > "$F/logs/michaels_fly125_standby_s$N.log"; EF=${PIPESTATUS[0]}
  echo "V3R3 seed=$N fit exit=$EF fit_wall_s=$(( $(date +%s) - T1 )) total_wall_s=$(( $(date +%s) - T0 ))"
  tail -3 "$F/logs/michaels_fly125_standby_s$N.log"
  [ $EF -ne 0 ] && dump_err "$F/grid/michaels_fly125_standby_s$N"
  $PY /tmp/summ.py "$F/restarts/michaels_fly125_standby__flight_v3__s$N.json" || true
  sync_out
}
for N in 0 1 2 3; do run_seed $N & sleep 20; done; wait
kill $SYNC_PID 2>/dev/null; sync_out
echo "V3R3_DONE total_wall_s=$(( $(date +%s) - T0 ))"
